import React, { useState } from 'react';
// import useNavigate ifใช้สำหรับเปลี่ยนหน้า
// import logo ถ้ามีเป็นไฟล์ภาพ

function Login() {
  const [email, setEmail] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  // TODO: เชื่อม backend เมื่อ submit อีเมลเพื่อขอ OTP (POST /api/auth/request-otp)
  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');
    try {
      // ที่นี่จะเรียก API ส่ง OTP
      // Example:
      // let res = await fetch('/api/auth/request-otp', {
      //   method: 'POST',
      //   headers: { 'Content-Type': 'application/json' },
      //   body: JSON.stringify({ email }),
      // });
      // ถ้า success ให้ redirect ไปหน้า /verify-otp พร้อม email
      // navigate(`/verify-otp?email=${email}`);
    } catch (err) {
      setError('ส่ง OTP ไม่สำเร็จ กรุณาลองใหม่');
    }
    setIsLoading(false);
  };

  return (
    <div className="min-h-screen flex flex-col lg:flex-row bg-neutral-50">
      {/* HERO/INFO Section - สื่อสารให้รู้ว่านี่คือเว็บอะไร */}
      <div className="lg:w-1/2 flex flex-col justify-center items-center bg-gradient-to-tr from-primary-400 via-primary-600 to-secondary-400 px-6 py-12 text-white relative">
        {/* Logo Brand */}
        <img src="/logo.png" alt="ClaimMate" className="w-20 h-20 mb-4 shadow-2xl rounded-2xl bg-white p-2" />
        <h1 className="text-4xl font-extrabold tracking-tight mb-2 drop-shadow-lg">ClaimMate</h1>
        <h2 className="lg:text-2xl text-lg font-bold mb-6 drop-shadow-md text-white/90">
          ระบบแจ้งเคลมประกัน <br /> สำหรับลูกค้า พนักงาน ศูนย์บริการ
        </h2>
        <ul className="space-y-3 mb-6 w-full max-w-sm">
          <li className="flex items-center gap-2">
            <span className="material-icons-round text-white bg-primary-500 rounded-full p-1">flash_on</span>
            เคลมง่าย รวดเร็ว ไม่ต้องโทร
          </li>
          <li className="flex items-center gap-2">
            <span className="material-icons-round text-white bg-secondary-500 rounded-full p-1">verified_user</span>
            ปลอดภัยกว่า ด้วย OTP ทุกครั้ง
          </li>
          <li className="flex items-center gap-2">
            <span className="material-icons-round text-white bg-green-500 rounded-full p-1">favorite</span>
            เชื่อมต่อข้อมูลทุกบทบาท
          </li>
        </ul>
        <div className="flex flex-wrap gap-8 mt-auto mb-8">
          <div className="text-center">
            <span className="text-3xl font-bold">1000+</span>
            <div className="text-white/70">ลูกค้าพึงพอใจ</div>
          </div>
          <div className="text-center">
            <span className="text-3xl font-bold">5000+</span>
            <div className="text-white/70">แจ้งเคลมผ่านเว็บ</div>
          </div>
          <div className="text-center">
            <span className="text-3xl font-bold">99%</span>
            <div className="text-white/70">ยืนยันความง่าย</div>
          </div>
        </div>
        <div className="absolute bottom-4 right-8 text-white/70 text-xs">
          © 2025 ClaimMate
        </div>
      </div>

      {/* LOGIN Section - สำหรับเข้าสู่ระบบ */}
      <div className="lg:w-1/2 flex items-center justify-center p-6 bg-neutral-50">
        <div className="bg-white w-full max-w-md rounded-2xl p-8 shadow-xl">
          <div className="flex flex-col items-center mb-6">
            <span className="material-icons-round text-5xl text-primary-500 animate-pulse mb-3 bg-gradient-to-r from-primary-400 to-secondary-400 rounded-full p-3 shadow-glow-primary">
              lock
            </span>
            <h2 className="text-2xl font-bold mb-1 text-neutral-dark">เข้าสู่ระบบเพื่อใช้งาน</h2>
            <div className="text-neutral-500 text-sm mb-3 text-center">
              ระบุอีเมลของคุณ<br />
              ระบบจะส่ง OTP ให้เข้าสู่ระบบอย่างปลอดภัย
            </div>
          </div>
          <form onSubmit={handleSubmit} className="space-y-5">
            <label className="block">
              <span className="text-neutral-700 font-medium">อีเมล</span>
              <input
                type="email"
                required
                className="w-full px-4 py-3 mt-1 rounded-xl border border-neutral-200 focus:ring-2 focus:ring-primary-400 bg-neutral-50 text-neutral-dark placeholder-neutral-400 font-medium transition duration-200"
                placeholder="example@email.com"
                value={email}
                onChange={e => setEmail(e.target.value)}
                disabled={isLoading}
                autoComplete="email"
              />
            </label>
            {!!error && (
              <div className="bg-error bg-opacity-20 border border-error text-error p-2 rounded">
                {error}
              </div>
            )}
            <button
              type="submit"
              disabled={isLoading}
              className={"w-full py-3 font-semibold rounded-xl bg-gradient-to-r from-primary-400 to-secondary-400 text-white shadow-md hover:scale-105 transition " +
                (isLoading ? 'opacity-50 cursor-not-allowed' : 'hover:shadow-xl animate-pulse')}
            >
              {isLoading ? 'กำลังส่ง...' : 'ขอ OTP / เข้าสู่ระบบ'}
            </button>
          </form>
          <div className="mt-6 text-sm text-center">
            ต้องการความช่วยเหลือ?{' '}
            <a href="tel:02-123-4567" className="text-primary-600 hover:underline">02-123-4567</a> หรือ
            <a href="mailto:support@claimmate.com" className="text-primary-600 hover:underline ml-1">
              support@claimmate.com
            </a>
          </div>
        </div>
      </div>
    </div>
  );
}

/*
  TODO:
  - เชื่อม backend:
    POST /api/auth/request-otp พร้อม email
    ถ้า success => redirect ไปหน้า verify-otp
    ถ้า error => แจ้งบนหน้าฟอร์ม
  - ดีไซน์ปรับ responsive ด้วย flex lg:flex-row/max-w-md/padding
